// Example: Safe redirect function
function safeRedirect(req, res, targetUrl) {
  // Whitelist of allowed domains or paths
  const allowedDomains = ['https://example.com', 'https://www.example.com'];
  const allowedPaths = ['/dashboard', '/profile'];

